# Generates correctly-rounded (CR) reference vectors for DetMath tests.
# Oracle: Python decimal at 60-80 significant digits (exp/ln are correctly rounded at the context
# precision per the decimal spec), converted to binary64 by float() (correctly rounded).
# Inputs are generated by a fixed-seed SplitMix64 (reproducible). Also records glibc's result
# (Python math.* calls the platform libm, the same library .NET Math.* binds to on Linux).
import struct, math, sys
from decimal import Decimal as D, getcontext, localcontext
def bits(f): return struct.unpack('<Q', struct.pack('<d', f))[0]
def fb(b): return struct.unpack('<d', struct.pack('<Q', b))[0]
M=(1<<64)-1
class SM:
    def __init__(s, seed): s.s = seed & M
    def next(s):
        s.s = (s.s + 0x9E3779B97F4A7C15) & M
        z = s.s
        z = ((z ^ (z >> 30)) * 0xBF58476D1CE4E5B9) & M
        z = ((z ^ (z >> 27)) * 0x94D049BB133111EB) & M
        return z ^ (z >> 31)
    def u(s): return (s.next() >> 11) * (1.0/9007199254740992.0)
rng = SM(17)
getcontext().prec = 70
def pi_dec():
    with localcontext() as c:
        c.prec = 130
        def atan_inv(n):
            x = D(1)/n; x2 = x*x; s = x; t = x; k = 1
            while True:
                t = -t*x2; k += 2; term = t/k
                if abs(term) < D(10)**-128: break
                s += term
            return s
        return +(16*atan_inv(5) - 4*atan_inv(239))
PI = pi_dec()
def cr_exp(x):
    with localcontext() as c:
        c.prec = 70; c.Emin = -999999; c.Emax = 999999
        return float(D(x).exp())
def cr_log(x):
    with localcontext() as c:
        c.prec = 70
        return float(D(x).ln())
def cr_pow(x, y):
    with localcontext() as c:
        c.prec = 90; c.Emin = -999999; c.Emax = 999999
        v = (D(y) * D(x).ln()).exp()
        try: return float(v)
        except OverflowError: return math.inf
def cr_cos(x):
    with localcontext() as c:
        c.prec = 130
        X = D(x)
        twopi = 2*PI
        k = (X / twopi).to_integral_value()
        r = X - k*twopi
        r2 = r*r; term = D(1); s = D(1); n = 0
        while True:
            n += 2
            term = -term * r2 / (n*(n-1))
            if abs(term) < D(10)**-125: break
            s += term
        c.prec = 70
        return float(+s)
def g(f, *a):
    try: return f(*a)
    except ValueError: return math.nan
    except OverflowError: return math.inf
out = []
def add(fn, x, y, cr, gl):
    out.append("%s %016x %016x %016x %016x" % (fn, bits(x), bits(y), bits(cr), bits(gl)))
def lin(a, b): return a + (b - a) * rng.u()
def logu(a, b): return math.exp(math.log(a) + (math.log(b) - math.log(a)) * rng.u())
N = int(sys.argv[1]) if len(sys.argv) > 1 else 1000
# ---- Exp ----
for _ in range(N): x = lin(-50.0, 5.0); add('exp', x, 0.0, cr_exp(x), math.exp(x))
for _ in range(N//2): x = lin(-745.0, 709.7); add('exp', x, 0.0, cr_exp(x), math.exp(x))
for _ in range(N//4): x = lin(-745.1, -708.0); add('exp', x, 0.0, cr_exp(x), math.exp(x))   # subnormal outputs
for _ in range(N//4): x = (1 if rng.u()<0.5 else -1) * logu(1e-300, 1e-3); add('exp', x, 0.0, cr_exp(x), math.exp(x))
for x in [0.0, -0.0, 1.0, -1.0, 709.78, 709.782712893384, -745.1332191019411, -745.1332191019412, -708.3964185322641, 1e-17, -1e-17, 0.5, 2.0**-30]:
    add('exp', x, 0.0, cr_exp(x), g(math.exp, x))
# ---- Log ----
for _ in range(N): x = logu(1e-300, 1.0); add('log', x, 0.0, cr_log(x), math.log(x))
for _ in range(N): x = logu(1.0, 1e8); add('log', x, 0.0, cr_log(x), math.log(x))
for _ in range(N//4): x = 1.0 + (1 if rng.u()<0.5 else -1) * logu(1e-15, 1e-2); add('log', x, 0.0, cr_log(x), math.log(x))
for _ in range(N//8): x = fb(1 + (rng.next() % ((1<<52)-1))); add('log', x, 0.0, cr_log(x), math.log(x))   # subnormal inputs
for _ in range(N//8): x = fb((rng.next() % 0x7fe0000000000000) + (1<<52)); add('log', x, 0.0, cr_log(x), math.log(x))  # all normals
for x in [1.0, 2.0, 0.5, 1e-300, 2.0**-1074, 1.7976931348623157e308, 10.0, math.e]:
    add('log', x, 0.0, cr_log(x), math.log(x))
# ---- Pow ----
for _ in range(N): x = logu(1e-12, 1.0); y = lin(-10.0, 10.0); add('pow', x, y, cr_pow(x, y), g(math.pow, x, y))    # CES s^rho, acc^(1/rho)
for _ in range(N): x = logu(1.0, 1e8); y = lin(0.3, 1.2); add('pow', x, y, cr_pow(x, y), g(math.pow, x, y))        # c P^beta
for n in range(0, 201): x = 1.2; y = float(n); add('pow', x, y, cr_pow(x, y), g(math.pow, x, y))                    # costGrowth^(n-1)
for _ in range(N//2): x = rng.u(); y = float(int(lin(0, 60))); add('pow', x, y, cr_pow(x, y), g(math.pow, x, y))     # (1-g)^levels
for _ in range(N//4): x = logu(1e-3, 1e3); y = lin(-200.0, 200.0); add('pow', x, y, cr_pow(x, y), g(math.pow, x, y))
# ---- Cos ----
for _ in range(N): u = rng.u(); x = 2.0 * math.pi * u; add('cos', x, 0.0, cr_cos(x), math.cos(x))                   # Box-Muller
for _ in range(N//2): x = lin(-1e5, 1e5); add('cos', x, 0.0, cr_cos(x), math.cos(x))
for k in range(1, 200): 
    x = float(D(k) * PI / 2); add('cos', x, 0.0, cr_cos(x), math.cos(x))                                            # near zeros
for x in [0.0, -0.0, 1e-10, 0.7853981633974483, 0.7853981633974484, 1.0, 3.141592653589793, 6.283185307179586, 268435456.0]:
    add('cos', x, 0.0, cr_cos(x), math.cos(x))
print("\n".join(out))
